function gemini_ai_assistant_activate()
{
    try {
        if (!Capsule::schema()->hasTable('mod_gemini_ai_logs')) {
            Capsule::schema()->create('mod_gemini_ai_logs', function ($table) {
                $table->increments('id');
                $table->integer('ticket_id')->unsigned();
                $table->text('user_message');
                $table->text('ai_response');
                $table->decimal('confidence_score', 3, 2);
                $table->string('mood_detected', 50);
                $table->string('response_type', 20);
                $table->timestamp('created_at');
            });
        }

        if (!Capsule::schema()->hasTable('mod_gemini_qa_pairs')) {
            Capsule::schema()->create('mod_gemini_qa_pairs', function ($table) {
                $table->increments('id');
                $table->text('question');
                $table->text('answer');
                $table->integer('priority')->default(1);
                $table->boolean('active')->default(true);
                $table->timestamp('created_at');
            });
        }

        if (!Capsule::schema()->hasTable('mod_gemini_ticket_analysis')) {
            Capsule::schema()->create('mod_gemini_ticket_analysis', function ($table) {
                $table->increments('id');
                $table->integer('ticket_id')->unsigned();
                $table->string('mood', 50);
                $table->decimal('escalation_level', 3, 2);
                $table->text('key_issues');
                $table->boolean('needs_human')->default(false);
                $table->timestamp('analyzed_at');
            });
        }

        if (!Capsule::schema()->hasTable('mod_gemini_api_logs')) {
            Capsule::schema()->create('mod_gemini_api_logs', function ($table) {
                $table->increments('id');
                $table->string('api_endpoint', 255);
                $table->text('request_data');
                $table->text('response_data');
                $table->integer('http_code');
                $table->string('curl_error', 255)->nullable();
                $table->decimal('response_time', 8, 4);
                $table->string('ticket_id', 20)->nullable();
                $table->string('status', 20); // success, error, failed
                $table->text('error_details')->nullable();
                $table->timestamp('created_at');
            });
        }

        // Training cache table
        if (!Capsule::schema()->hasTable('mod_gemini_training_cache')) {
            Capsule::schema()->create('mod_gemini_training_cache', function ($table) {
                $table->increments('id');
                $table->integer('department_id')->unsigned()->nullable();
                $table->string('category', 50)->default('general');
                $table->text('question_summary');
                $table->text('answer_summary');
                $table->integer('source_ticket_id')->unsigned();
                $table->decimal('relevance_score', 3, 2)->default(0.5);
                $table->timestamp('created_at');
                $table->timestamp('updated_at')->nullable();
            });
        }

        // Escalation tracking table
        if (!Capsule::schema()->hasTable('mod_gemini_escalations')) {
            Capsule::schema()->create('mod_gemini_escalations', function ($table) {
                $table->increments('id');
                $table->integer('ticket_id')->unsigned();
                $table->integer('client_id')->unsigned();
                $table->text('reason');
                $table->string('priority', 20)->default('high');
                $table->boolean('admin_notified')->default(false);
                $table->timestamp('admin_email_sent_at')->nullable();
                $table->boolean('resolved')->default(false);
                $table->timestamp('resolved_at')->nullable();
                $table->timestamp('created_at');
            });
        }

        // Reply Queue for Autopilot Delay
        if (!Capsule::schema()->hasTable('mod_gemini_reply_queue')) {
            Capsule::schema()->create('mod_gemini_reply_queue', function ($table) {
                $table->increments('id');
                $table->integer('ticket_id')->unsigned();
                $table->text('user_message');
                $table->string('status', 20)->default('pending'); // pending, processing, completed, failed
                $table->timestamp('scheduled_at');
                $table->timestamp('created_at');
            });
        }

        return [
            'status' => 'success',
            'description' => 'Neko AI Assistant activated successfully with all database tables.'
        ];
    } catch (Exception $e) {
        return [
            'status' => 'error',
            'description' => 'Activation failed: ' . $e->getMessage()
        ];
    }
}

function gemini_ai_assistant_deactivate()
{
    try {
        // Keep data for future use, just deactivate
        return [
            'status' => 'success',
            'description' => 'Neko AI Assistant deactivated. Data preserved.'
        ];
    } catch (Exception $e) {
        return [
            'status' => 'error',
            'description' => 'Deactivation failed: ' . $e->getMessage()
        ];
    }
}

function gemini_ai_assistant_clientarea($vars)
{
    if (isset($_POST['action'])) {
        $action = $_POST['action'];
        $tid_mask = $_POST['tid_mask'] ?? '';
        $c = $_POST['c'] ?? '';

        if (!$tid_mask || !$c) {
            ob_clean();
            header('Content-Type: application/json');
            echo json_encode(['success' => false, 'error' => 'Missing ticket credentials']);
            exit;
        }

        $ticket = Capsule::table('tbltickets')->where('tid', $tid_mask)->where('c', $c)->first();
        if (!$ticket) {
            ob_clean();
            header('Content-Type: application/json');
            echo json_encode(['success' => false, 'error' => 'Ticket not found or unauthorized']);
            exit;
        }

        $ticket_id = $ticket->id;

        if ($action == 'client_generate_ai_reply') {
            $mode = $_POST['reply_mode'] ?? 'generate';
            $lang = $_POST['reply_lang'] ?? 'auto';
            $current_message = $_POST['current_message'] ?? '';

            // Get ticket message(s) for context
            $message = Capsule::table('tbltickets')->where('id', $ticket_id)->value('message');

            $analysis = analyze_ticket_content($message, $ticket_id);
            $ai_response = generate_ai_ticket_response($message, $ticket_id, $analysis, $mode, $current_message, $lang, 'client');

            ob_clean();
            header('Content-Type: application/json');
            echo json_encode($ai_response);
            exit;
        }

        if ($action == 'client_analyze_ticket_mood') {
            $message = Capsule::table('tbltickets')->where('id', $ticket_id)->value('message');
            $analysis = analyze_ticket_content($message, $ticket_id);

            ob_clean();
            header('Content-Type: application/json');
            echo json_encode(array_merge(['success' => true], $analysis));
            exit;
        }
    }

    // Return empty output for non-AJAX visits
    return [
        'pagetitle' => 'AI Assistant',
        'breadcrumb' => ['index.php?m=gemini_ai_assistant' => 'AI Assistant'],
        'templatefile' => 'clientarea',
        'requirelogin' => false,
        'vars' => []
    ];
}

function gemini_ai_assistant_output($vars)
{
    $modulelink = $vars['modulelink'];
    $version = $vars['version'];
    $LANG = $vars['_lang'];

    // Handle form submissions
    if (isset($_POST['action'])) {
        handle_admin_actions($vars);
    }

    display_admin_interface($vars);
}

function redirect_with_message($message, $type = 'success')
{
    $_SESSION['gemini_flash_message'] = [
        'type' => $type,
        'message' => $message,
    ];
    header("Location: addonmodules.php?module=gemini_ai_assistant");
    exit;
}

function handle_admin_actions($vars)
{
    if ($_POST['action'] == 'add_qa') {
        Capsule::table('mod_gemini_qa_pairs')->insert([
            'question' => $_POST['question'],
            'answer' => $_POST['answer'],
            'priority' => $_POST['priority'],
            'created_at' => date('Y-m-d H:i:s')
        ]);
        echo '<div class="alert alert-success">QA pair added successfully!</div>';
    } elseif ($_POST['action'] == 'delete_qa') {
        Capsule::table('mod_gemini_qa_pairs')->where('id', $_POST['qa_id'])->delete();
        echo '<div class="alert alert-success">QA pair deleted successfully!</div>';
    } elseif ($_POST['action'] == 'test_api') {
        test_gemini_api_connection($vars);
    } elseif ($_POST['action'] == 'clear_logs') {
        $days = (int) $_POST['clear_days'];
        $date_threshold = date('Y-m-d H:i:s', strtotime("-$days days"));

        $deleted_api = Capsule::table('mod_gemini_api_logs')->where('created_at', '<', $date_threshold)->delete();
        $deleted_ai = Capsule::table('mod_gemini_ai_logs')->where('created_at', '<', $date_threshold)->delete();

        redirect_with_message("Cleared " . ($deleted_api + $deleted_ai) . " log records older than {$days} days.");

    } elseif ($_POST['action'] == 'train_from_tickets') {
        $department_id = !empty($_POST['department_id']) ? (int) $_POST['department_id'] : null;
        $limit = (int) ($_POST['training_limit'] ?? 100);
        $result = train_from_historical_tickets($department_id, $limit);
        if ($result['success']) {
            redirect_with_message($result['message']);
        } else {
            redirect_with_message($result['message'], 'warning');
        }
    } elseif ($_POST['action'] == 'clear_training_cache') {
        $deleted = Capsule::table('mod_gemini_training_cache')->delete();
        redirect_with_message("Cleared {$deleted} training cache entries. You can re-train from tickets.");
    } elseif ($_POST['action'] == 'resolve_escalation') {
        $escalation_id = (int) $_POST['escalation_id'];
        Capsule::table('mod_gemini_escalations')->where('id', $escalation_id)->update([
            'resolved' => true,
            'resolved_at' => date('Y-m-d H:i:s'),
        ]);
        redirect_with_message('Escalation marked as resolved.');
    }
}

function test_gemini_api_connection($vars)
{
    $config = get_gemini_config();

    if (empty($config['gemini_api_key'])) {
        echo '<div class="alert alert-danger">API Key is not configured. Please enter your Gemini API key.</div>';
        return;
    }

    echo '<div class="alert alert-info"><strong>Testing API Connection...</strong></div>';

    $test_prompt = "Please respond with just the word 'SUCCESS' if you can read this message. This is a test of the API connection.";

    $start_time = microtime(true);
    $result = call_gemini_api($test_prompt, $config, 'test_connection');
    $response_time = microtime(true) - $start_time;

    echo '<div class="well">';
    echo '<h4>API Test Results:</h4>';
    echo '<table class="table table-bordered">';
    echo '<tr><td><strong>API Key Status:</strong></td><td>' . (empty($config['gemini_api_key']) ? '<span class="label label-danger">Missing</span>' : '<span class="label label-success">Configured</span>') . '</td></tr>';
    echo '<tr><td><strong>Response Time:</strong></td><td>' . number_format($response_time, 3) . ' seconds</td></tr>';
    echo '<tr><td><strong>HTTP Status:</strong></td><td>' . ($result['http_code'] ?? 'N/A') . '</td></tr>';

    if ($result['success']) {
        echo '<tr><td><strong>API Status:</strong></td><td><span class="label label-success">SUCCESS</span></td></tr>';
        echo '<tr><td><strong>Response:</strong></td><td>' . htmlspecialchars($result['response']) . '</td></tr>';
        echo '<tr><td><strong>Test Result:</strong></td><td><span class="label label-success">API Connection Working Perfectly</span></td></tr>';
    } else {
        echo '<tr><td><strong>API Status:</strong></td><td><span class="label label-danger">FAILED</span></td></tr>';
        echo '<tr><td><strong>Error:</strong></td><td>' . htmlspecialchars($result['error']) . '</td></tr>';
        echo '<tr><td><strong>CURL Error:</strong></td><td>' . htmlspecialchars($result['curl_error'] ?? 'None') . '</td></tr>';
        echo '<tr><td><strong>Test Result:</strong></td><td><span class="label label-danger">API Connection Failed - Check API Key and Network</span></td></tr>';
    }

    echo '</table>';

    // Show recent API logs for debugging
    $recent_logs = Capsule::table('mod_gemini_api_logs')
        ->orderBy('created_at', 'desc')
        ->limit(5)
        ->get();

    if ($recent_logs->count() > 0) {
        echo '<h5>Recent API Calls:</h5>';
        echo '<div style="max-height: 300px; overflow-y: auto;">';
        foreach ($recent_logs as $log) {
            echo '<div class="api-log-entry" style="border: 1px solid #ddd; margin: 5px 0; padding: 10px; background: #f9f9f9;">';
            echo '<strong>Time:</strong> ' . $log->created_at . ' | ';
            echo '<strong>Status:</strong> <span class="label label-' . ($log->status == 'success' ? 'success' : 'danger') . '">' . $log->status . '</span> | ';
            echo '<strong>HTTP Code:</strong> ' . $log->http_code . ' | ';
            echo '<strong>Response Time:</strong> ' . number_format($log->response_time, 3) . 's';
            if ($log->curl_error) {
                echo ' | <strong>CURL Error:</strong> ' . htmlspecialchars($log->curl_error);
            }
            echo '</div>';
        }
        echo '</div>';
    }

    echo '</div>';
}

function display_admin_interface($vars)
{
    $qa_pairs = Capsule::table('mod_gemini_qa_pairs')->orderBy('priority', 'desc')->get();
    $recent_logs = Capsule::table('mod_gemini_ai_logs')
        ->join('tbltickets', 'mod_gemini_ai_logs.ticket_id', '=', 'tbltickets.id')
        ->select('mod_gemini_ai_logs.*', 'tbltickets.tid')
        ->orderBy('mod_gemini_ai_logs.created_at', 'desc')
        ->limit(50)
        ->get();

    $api_logs = Capsule::table('mod_gemini_api_logs')
        ->orderBy('created_at', 'desc')
        ->limit(100)
        ->get();

    // Get mood distribution data
    $mood_data = Capsule::table('mod_gemini_ai_logs')
        ->select('mood_detected', Capsule::raw('COUNT(*) as count'))
        ->groupBy('mood_detected')
        ->get();

    // Get daily activity data (last 30 days)
    $activity_data = Capsule::table('mod_gemini_ai_logs')
        ->select(Capsule::raw('DATE(created_at) as date'), Capsule::raw('COUNT(*) as count'))
        ->where('created_at', '>=', date('Y-m-d', strtotime('-30 days')))
        ->groupBy('date')
        ->orderBy('date', 'asc')
        ->get();

    // Fill missing dates for last 30 days
    $dates = [];
    for ($i = 0; $i < 30; $i++) {
        $date = date('Y-m-d', strtotime("-$i days"));
        $dates[$date] = 0;
    }

    // Merge real data
    foreach ($activity_data as $row) {
        $dates[$row->date] = $row->count;
    }

    // Rebuild in chronological order
    $activity_data = collect(array_map(function ($date, $count) {
        return (object) ['date' => $date, 'count' => $count];
    }, array_reverse(array_keys($dates)), array_reverse(array_values($dates))));

    // Get confidence score distribution
    $confidence_data = Capsule::table('mod_gemini_ai_logs')
        ->select(
            Capsule::raw('SUM(CASE WHEN confidence_score >= 0.8 THEN 1 ELSE 0 END) as high'),
            Capsule::raw('SUM(CASE WHEN confidence_score >= 0.6 AND confidence_score < 0.8 THEN 1 ELSE 0 END) as medium'),
            Capsule::raw('SUM(CASE WHEN confidence_score < 0.6 THEN 1 ELSE 0 END) as low')
        )
        ->first();

    // Training data
    $training_cache_count = Capsule::table('mod_gemini_training_cache')->count();
    $training_data = Capsule::table('mod_gemini_training_cache')
        ->orderBy('relevance_score', 'desc')
        ->limit(50)
        ->get();
    $departments = Capsule::table('tblticketdepartments')->get();

    // Escalation data
    $escalations = Capsule::table('mod_gemini_escalations')
        ->leftJoin('tbltickets', 'mod_gemini_escalations.ticket_id', '=', 'tbltickets.id')
        ->leftJoin('tblclients', 'mod_gemini_escalations.client_id', '=', 'tblclients.id')
        ->select('mod_gemini_escalations.*', 'tbltickets.tid', 'tbltickets.title as ticket_subject',
            Capsule::raw("CONCAT(tblclients.firstname, ' ', tblclients.lastname) as client_name"),
            'tblclients.email as client_email')
        ->orderBy('mod_gemini_escalations.created_at', 'desc')
        ->limit(50)
        ->get();
    $active_escalations = Capsule::table('mod_gemini_escalations')->where('resolved', false)->count();
    ?>

