            echo implode(', ', array_map(function ($item) {
                return "'" . addslashes($item->mood_detected) . "'";
            }, $mood_data->toArray()));
            ?>];
            const moodCounts = [<?php
            echo implode(', ', array_map(function ($item) {
                return $item->count;
            }, $mood_data->toArray()));
            ?>];

            const moodColorsMap = {
                'happy': '#2ecc71',
                'angry': '#e74c3c',
                'neutral': '#95a5a6',
                'sad': '#3498db',
                'confused': '#f39c12',
                'frustrated': '#e67e22',
                'satisfied': '#27ae60',
                'urgent': '#c0392b',
                'calm': '#16a085'
            };

            const moodColors = moodLabels.map(label => moodColorsMap[label.toLowerCase()] || '#7f8c8d');

            new Chart(moodCtx, {
                type: 'doughnut',
                data: {
                    labels: moodLabels,
                    datasets: [{
                        data: moodCounts,
                        backgroundColor: moodColors,
                        borderColor: '#fff',
                        borderWidth: 3,
                        hoverOffset: 15
                    }]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    plugins: {
                        legend: {
                            position: 'right',
                            labels: {
                                padding: 20,
                                usePointStyle: true,
                                pointStyle: 'circle'
                            }
                        },
                        tooltip: {
                            callbacks: {
                                label: function (context) {
                                    const label = context.label || '';
                                    const value = context.raw || 0;
                                    const total = context.dataset.data.reduce((a, b) => a + b, 0);
                                    const percentage = total > 0 ? Math.round((value / total) * 100) : 0;
                                    return `${label}: ${value} (${percentage}%)`;
                                }
                            }
                        }
                    },
                    cutout: '60%'
                }
            });

            // Activity Chart
            const activityCtx = document.getElementById('activityChart').getContext('2d');
            const activityLabels = [<?php
            echo implode(', ', array_map(function ($item) {
                return "'" . date('M j', strtotime($item->date)) . "'";
            }, $activity_data->toArray()));
            ?>];
            const activityCounts = [<?php
            echo implode(', ', array_map(function ($item) {
                return $item->count;
            }, $activity_data->toArray()));
            ?>];

            new Chart(activityCtx, {
                type: 'line',
                data: {
                    labels: activityLabels,
                    datasets: [{
                        label: 'AI Responses',
                        data: activityCounts,
                        borderColor: '#3498db',
                        backgroundColor: 'rgba(52, 152, 219, 0.1)',
                        borderWidth: 3,
                        pointRadius: 4,
                        pointHoverRadius: 8,
                        pointBackgroundColor: '#3498db',
                        pointBorderColor: '#fff',
                        pointBorderWidth: 2,
                        tension: 0.4,
                        fill: true
                    }]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    plugins: {
                        legend: {
                            display: false
                        },
                        tooltip: {
                            backgroundColor: 'rgba(255, 255, 255, 0.95)',
                            titleColor: '#2c3e50',
                            bodyColor: '#2c3e50',
                            borderColor: '#3498db',
                            borderWidth: 1,
                            cornerRadius: 8,
                            callbacks: {
                                label: function (context) {
                                    return ` ${context.parsed.y} AI Responses`;
                                }
                            }
                        }
                    },
                    scales: {
                        x: {
                            grid: {
                                color: 'rgba(0, 0, 0, 0.05)'
                            },
                            ticks: {
                                color: '#7f8c8d'
                            }
                        },
                        y: {
                            beginAtZero: true,
                            grid: {
                                color: 'rgba(0, 0, 0, 0.05)'
                            },
                            ticks: {
                                color: '#7f8c8d',
                                stepSize: 1
                            }
                        }
                    }
                }
            });

            // Confidence Chart
            const confidenceCtx = document.getElementById('confidenceChart').getContext('2d');
            new Chart(confidenceCtx, {
                type: 'bar',
                data: {
                    labels: ['High (≥80%)', 'Medium (60–79%)', 'Low (<60%)'],
                    datasets: [{
                        label: 'Number of Responses',
                        data: [
                            <?php echo $confidence_data->high ?? 0; ?>,
                            <?php echo $confidence_data->medium ?? 0; ?>,
                            <?php echo $confidence_data->low ?? 0; ?>
                        ],
                        backgroundColor: [
                            'rgba(46, 204, 113, 0.8)',
                            'rgba(243, 156, 18, 0.8)',
                            'rgba(231, 76, 60, 0.8)'
                        ],
                        borderColor: [
                            '#27ae60',
                            '#d35400',
                            '#c0392b'
                        ],
                        borderWidth: 2,
                        borderRadius: 8,
                        borderSkipped: false,
                    }]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    plugins: {
                        legend: {
                            display: false
                        }
                    },
                    scales: {
                        y: {
                            beginAtZero: true,
                            grid: {
                                color: 'rgba(0, 0, 0, 0.05)'
                            },
                            ticks: {
                                color: '#7f8c8d',
                                stepSize: 1
                            }
                        },
                        x: {
                            grid: {
                                display: false
                            },
                            ticks: {
                                color: '#7f8c8d'
                            }
                        }
                    }
                }
            });

            // Update confidence score colors dynamically
            document.querySelectorAll('.confidence-score').forEach(score => {
                const value = parseFloat(score.dataset.score);
                if (value >= 0.8) {
                    score.style.background = '#d4edda';
                    score.style.color = '#155724';
                } else if (value >= 0.6) {
                    score.style.background = '#fff3cd';
                    score.style.color = '#856404';
                } else {
                    score.style.background = '#f8d7da';
                    score.style.color = '#721c24';
                }
            });
        });

        function viewLogDetails(logId) {
            fetch('addonmodules.php?module=gemini_ai_assistant', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded',
                },
                body: 'action=get_log_details&log_id=' + logId
            })
                .then(response => response.text())
                .then(data => {
                    document.getElementById('logDetailsContent').innerHTML = data;
                    $('#logDetailsModal').modal('show');
                })
                .catch(error => {
                    document.getElementById('logDetailsContent').innerHTML = 'Error loading log details: ' + error;
                    $('#logDetailsModal').modal('show');
                });
        }
    </script>
    <?php
}

// Add this new function to handle log details
add_hook('AdminAreaHeaderOutput', 1, function ($vars) {
    if ($vars['filename'] == 'addonmodules' && $_GET['module'] == 'gemini_ai_assistant' && $_POST['action'] == 'get_log_details') {
        $log_id = (int) $_POST['log_id'];
        $log = Capsule::table('mod_gemini_api_logs')->where('id', $log_id)->first();

        if ($log) {
            echo '<div class="log-details">';
            echo '<h4>Request Data:</h4>';
            echo '<pre style="background: #f8f9fa; padding: 10px; border-radius: 5px; max-height: 200px; overflow-y: auto;">';
            echo htmlspecialchars($log->request_data);
            echo '</pre>';

            echo '<h4>Response Data:</h4>';
            echo '<pre style="background: #f8f9fa; padding: 10px; border-radius: 5px; max-height: 200px; overflow-y: auto;">';
            echo htmlspecialchars($log->response_data);
            echo '</pre>';

            echo '<h4>Technical Details:</h4>';
            echo '<table class="table table-bordered">';
            echo '<tr><td><strong>CURL Error:</strong></td><td>' . ($log->curl_error ? htmlspecialchars($log->curl_error) : 'None') . '</td></tr>';
            echo '<tr><td><strong>Error Details:</strong></td><td>' . ($log->error_details ? htmlspecialchars($log->error_details) : 'None') . '</td></tr>';
            echo '<tr><td><strong>Endpoint:</strong></td><td>' . htmlspecialchars($log->api_endpoint) . '</td></tr>';
            echo '</table>';
            echo '</div>';
        } else {
            echo 'Log entry not found.';
        }
        exit;
    }
});

function get_mood_badge_class($mood)
{
    $mood_classes = [
        'calm' => 'success',
        'satisfied' => 'success',
        'neutral' => 'info',
        'frustrated' => 'warning',
        'angry' => 'danger',
        'urgent' => 'danger'
    ];

    return isset($mood_classes[strtolower($mood)]) ? $mood_classes[strtolower($mood)] : 'default';
}
